<script setup lang="ts">
import { ref } from 'vue';import { Plus, LogIn, RefreshCw, Trash2, LogOut, ShieldCheck, UsersRound, Pencil } from 'lucide-vue-next'
import { useAppStore, loginLabels, dateLabel } from '../store';import { platforms } from '../../../shared/platforms';import type { Account, PlatformId } from '../../../shared/contracts';import PlatformMark from '../components/PlatformMark.vue';import Modal from '../components/Modal.vue'
const store=useAppStore();const adding=ref(false),platform=ref<PlatformId>('chaoxing'),label=ref(''),confirm=ref<Account|null>(null),rename=ref<Account|null>(null)
async function add(){const a=await store.run<Account>({type:'account.add',platform:platform.value,label:label.value.trim()});if(a){adding.value=false;label.value='';store.workbench(a.platform);await store.run({type:'account.open',accountId:a.id})}}
async function open(a:Account){store.workbench(a.platform);await store.run({type:'account.open',accountId:a.id})}
async function remove(){if(confirm.value){const r=await store.run({type:'account.delete',accountId:confirm.value.id},'账号及其关联的本地数据已删除');if(r!==undefined)confirm.value=null}}
async function saveRename(){if(rename.value){const r=await store.run({type:'account.rename',accountId:rename.value.id,label:label.value});if(r!==undefined)rename.value=null}}
</script>
<template><div class="page"><div class="page-heading"><div><p class="eyebrow">ACCOUNTS</p><h1>账号管理</h1><p class="subtitle">每个账号都有独立空间，你的登录凭据只留在本机。</p></div><button class="button primary" @click="adding=true;label=''" data-testid="add-account"><Plus :size="17"/>添加账号</button></div>
 <div class="info-banner"><ShieldCheck :size="20"/><p>请在平台原始页面登录。这里不收集密码、验证码或 Cookie，也不会把账号上传到服务器。</p></div>
 <section v-for="p in platforms" :key="p.id" class="account-section"><div class="section-heading"><div class="heading-inline"><PlatformMark :platform="p.id" small/><h2>{{p.name}}</h2><span class="muted">{{store.accounts.filter(a=>a.platform===p.id).length}} 个账号</span></div><button class="text-button" @click="platform=p.id;label='';adding=true"><Plus :size="15"/>添加{{p.name==='中国大学 MOOC'?' MOOC':p.name}}账号</button></div>
 <div v-if="!store.accounts.some(a=>a.platform===p.id)" class="empty-account"><UsersRound :size="24"/><span>还没有连接账号</span><span class="muted">添加后即可在工作台登录。</span></div>
 <div v-else class="account-grid"><article v-for="a in store.accounts.filter(a=>a.platform===p.id)" :key="a.id" class="panel account-card"><div class="account-card-top"><div class="account-avatar">{{a.label.slice(0,1)}}</div><div class="grow"><h3>{{a.label}}</h3><span :class="['badge',a.loginStatus==='logged-in'?'green':'neutral']">{{loginLabels[a.loginStatus]}}</span></div><button class="icon-button" aria-label="修改账号备注" @click="rename=a;label=a.label"><Pencil :size="16"/></button></div><p class="account-meta">添加于 {{dateLabel(a.createdAt)}} · 独立登录会话</p><div class="account-actions"><button class="button compact primary-soft" :disabled="!!store.busy" @click="open(a)"><LogIn :size="15"/>打开登录</button><button class="button compact" :disabled="!!store.busy" @click="store.run({type:'account.check',accountId:a.id},'登录状态已检查')"><RefreshCw :size="14"/>检查状态</button><button class="icon-button" aria-label="退出账号登录" :disabled="!!store.busy" @click="store.run({type:'account.logout',accountId:a.id},'已退出登录，并取消该账号的未结束任务')"><LogOut :size="16"/></button><button class="icon-button danger" aria-label="删除账号" @click="confirm=a"><Trash2 :size="16"/></button></div></article></div></section>
 <Modal v-if="adding" title="连接一个学习账号" @close="adding=false"><form @submit.prevent="add"><label class="field">课程平台<select v-model="platform"><option v-for="p in platforms" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label class="field">账号备注<input v-model="label" placeholder="例如：我的学习通账号" maxlength="40" required data-testid="account-label"/></label><div class="subtle-box">这里只填写方便你辨认的备注。下一步会打开平台自己的登录页面，请在那里输入账号与密码。</div><div class="modal-actions"><button class="button" type="button" @click="adding=false">取消</button><button class="button primary" type="submit" :disabled="!!store.busy||!label.trim()">添加并打开登录</button></div></form></Modal>
 <Modal v-if="rename" title="修改账号备注" @close="rename=null"><form @submit.prevent="saveRename"><label class="field">备注名称<input v-model="label" maxlength="40" required/></label><div class="modal-actions"><button class="button primary" :disabled="!!store.busy||!label.trim()">保存备注</button></div></form></Modal>
 <Modal v-if="confirm" title="删除本地账号？" @close="confirm=null"><p>将删除「{{confirm.label}}」的登录会话、课程缓存、任务和学习记录，并停止相关播放。</p><p class="muted">其他账号不受影响。这不会注销你在网课平台上的账号。</p><div class="modal-actions"><button class="button" @click="confirm=null">保留账号</button><button class="button danger-solid" :disabled="!!store.busy" @click="remove">确认删除本地数据</button></div></Modal>
</div></template>
